use boa_engine::{Context, JsValue, Source, evaluation::EvaluationHandle};
use std::{thread, time::Duration};

fn check(name: &str, ok: bool) {
    println!("{} {name}", if ok { "PASS" } else { "FAIL" });
}

fn is_cancelled(err: &boa_engine::JsError) -> bool {
    err.to_string().contains("the evaluation was cancelled")
}

fn main() {
    // 1. Cancelling from another thread stops an infinite loop.
    {
        let mut ctx = Context::default();
        let handle = EvaluationHandle::new();
        let remote = handle.clone();
        thread::spawn(move || {
            thread::sleep(Duration::from_millis(100));
            remote.cancel();
        });
        let res = ctx.eval_with_evaluation(Source::from_bytes("while (true) {}"), &handle);
        check("loop cancelled from another thread", matches!(&res, Err(e) if is_cancelled(e)));
    }

    // 2. try/catch cannot swallow the cancellation.
    {
        let mut ctx = Context::default();
        let handle = EvaluationHandle::new();
        handle.cancel();
        let res = ctx.eval_with_evaluation(
            Source::from_bytes("try { while (true) {} } catch (e) { 'caught' }"),
            &handle,
        );
        check("try/catch does not swallow cancel", matches!(&res, Err(e) if is_cancelled(e)));
    }

    // 3. Context stays usable after a cancelled evaluation.
    {
        let mut ctx = Context::default();
        let handle = EvaluationHandle::new();
        handle.cancel();
        let _ = ctx.eval_with_evaluation(Source::from_bytes("1 + 1"), &handle);
        let res = ctx.eval(Source::from_bytes("1 + 1")).expect("plain eval");
        check("context reusable after cancel", res == JsValue::from(2));
    }

    // 4. Cancelling a child does not affect its parent.
    {
        let mut ctx = Context::default();
        let parent = EvaluationHandle::new();
        let child = parent.child();
        child.cancel();
        let parent_ok = ctx.eval_with_evaluation(Source::from_bytes("1 + 1"), &parent);
        check("child cancel leaves parent running", parent_ok == Ok(JsValue::from(2)));
        let child_res = ctx.eval_with_evaluation(Source::from_bytes("1 + 1"), &child);
        check("child cancel stops child", matches!(&child_res, Err(e) if is_cancelled(e)));
    }

    // 5. Cancelling a parent stops its children.
    {
        let mut ctx = Context::default();
        let parent = EvaluationHandle::new();
        let child = parent.child();
        parent.cancel();
        check("parent cancel reaches child", child.is_cancelled());
        let res = ctx.eval_with_evaluation(Source::from_bytes("1 + 1"), &child);
        check("parent cancel stops child eval", matches!(&res, Err(e) if is_cancelled(e)));
    }

    // 6. Draining skips only the cancelled evaluation's jobs.
    {
        let mut ctx = Context::default();
        ctx.eval(Source::from_bytes("var log = []; Promise.resolve().then(() => log.push('b'));"))
            .expect("unrelated job");
        let a = EvaluationHandle::new();
        ctx.eval_with_evaluation(
            Source::from_bytes("Promise.resolve().then(() => log.push('a'));"),
            &a,
        )
        .expect("owned job");
        a.cancel();
        let drain = ctx.run_jobs_with_evaluation(&a);
        let log = ctx.eval(Source::from_bytes("log.join()")).expect("log");
        check(
            "drain for cancelled evaluation stops before running jobs",
            matches!(&drain, Err(e) if is_cancelled(e)) && log == JsValue::from(boa_engine::js_string!("")),
        );
        ctx.run_jobs().expect("run remaining");
        let log = ctx.eval(Source::from_bytes("log.join()")).expect("log");
        check(
            "cancelled job skipped, unrelated job still runs",
            log == JsValue::from(boa_engine::js_string!("b")),
        );
    }

    // 7. Cancelling while a queued job runs stops the drain; the queue is not cleared.
    {
        let mut ctx = Context::default();
        let a = EvaluationHandle::new();
        ctx.eval_with_evaluation(
            Source::from_bytes("var done = false; Promise.resolve().then(() => { while (true) {} }); Promise.resolve().then(() => { done = true; });"),
            &a,
        )
        .expect("jobs");
        let remote = a.clone();
        thread::spawn(move || {
            thread::sleep(Duration::from_millis(100));
            remote.cancel();
        });
        let drain = ctx.run_jobs_with_evaluation(&a);
        check("drain stops when running job's evaluation is cancelled", matches!(&drain, Err(e) if is_cancelled(e)));
    }

    // 8. Untouched evaluation without a handle still behaves as before.
    {
        let mut ctx = Context::default();
        let res = ctx.eval(Source::from_bytes("[1, 2, 3].map(x => x * 2).join()")).expect("eval");
        check("plain eval unchanged", res == JsValue::from(boa_engine::js_string!("2,4,6")));
    }
}
EOF
